using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Check whether a specific feature flag is enabled.")]
    public static string CheckFeatureFlag(
        [Description("The name of the feature flag to check (e.g., DarkMode, BetaAccess)")] string flagName)
    {
        var flags = new Dictionary<string, bool>(StringComparer.OrdinalIgnoreCase)
        {
            ["DarkMode"] = true,
            ["BetaAccess"] = false,
            ["Notifications"] = true
        };

        if (flags.TryGetValue(flagName, out var enabled))
            return $"Feature '{flagName}' is {(enabled ? "enabled" : "disabled")}.";

        return $"Feature '{flagName}' not found. Available: {string.Join(", ", flags.Keys)}";
    }

    [McpServerTool, Description("Validate a configuration key-value pair against known constraints.")]
    public static string ValidateConfig(
        [Description("Configuration key to validate")] string key,
        [Description("Proposed value for the key")] string value)
    {
        return key.ToLower() switch
        {
            "maxretries" when int.TryParse(value, out var n) && n is >= 1 and <= 10
                => $"Valid: MaxRetries={n}",
            "maxretries"
                => "Invalid: MaxRetries must be an integer between 1 and 10.",
            "timeoutseconds" when int.TryParse(value, out var t) && t is >= 5 and <= 300
                => $"Valid: TimeoutSeconds={t}",
            "timeoutseconds"
                => "Invalid: TimeoutSeconds must be an integer between 5 and 300.",
            _ => $"Unknown config key: '{key}'. Known keys: MaxRetries, TimeoutSeconds."
        };
    }
}
